CREATE TABLE IF NOT EXISTS students (id CHAR(36) PRIMARY KEY,student_no VARCHAR(80) NOT NULL UNIQUE,full_name VARCHAR(180) NOT NULL,photo_url VARCHAR(1024) NULL,class_name VARCHAR(120) NULL,program_name VARCHAR(160) NULL,academic_year VARCHAR(32) NULL,status VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS guardian_relationships (id CHAR(36) PRIMARY KEY,guardian_user_id CHAR(36) NOT NULL,student_id CHAR(36) NOT NULL,relationship VARCHAR(40) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'PENDING',approved_by CHAR(36) NULL,approved_at DATETIME(6) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE KEY uq_guardian_student(guardian_user_id,student_id),INDEX idx_rel_guardian(guardian_user_id,status));
CREATE TABLE IF NOT EXISTS attendance (id CHAR(36) PRIMARY KEY,student_id CHAR(36) NOT NULL,attendance_date DATE NOT NULL,status VARCHAR(32) NOT NULL,note VARCHAR(500) NULL,recorded_by CHAR(36) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE KEY uq_att_student_date(student_id,attendance_date));
